"""
Builds benchmarks/atlas.bb with blitzcc, runs it and prints the frame times and what the frames cost: a field of cubes with many
different small textures. The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/atlas.py [--blitzcc PATH] [--textures N] [--objects N] [--backdrop N] [--sprites N] [--frames N] [--size WxH] [--no-atlas]
                                 [--debug] [--profile] [--label NAME] [--shot FILE] [--no-save]

--no-atlas sets BLITZ_NO_TEXTURE_ATLAS=1, for the run to compare with (the original Blitz3D has no merging and ignores it).
"--quick" is 40 textures, 400 objects and 30 frames for a look whether it works. -d builds without optimization (which BLITZ_FPS
profiling needs together with --profile); the build configuration is part of the result so runs are not mixed up.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the
folder with bin\\ in it unless it is set). It has no -O3 and no --profile, and no draw counters (they are 0), and it can have at most 16383 sprites.

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import argparse
import csv
import datetime
import json
import os
import platform
import re
import shutil
import sys
import tempfile
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../tools"))
import procutil  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)


# Direct3D 7 limits the window to 2048 in each direction (measured on Areldir: 2048x2048 works, 2049x1080 and 500x3000 fail): the original Blitz3D then stops with
# "Unable to create 3D Scene".
ORIGINAL_MAX_SIZE = 2048

def find_compiler(given):
    if given:
        return given
    for candidate in (os.path.join(ROOT, "build", "code_compiler", "blitzcc"), os.path.join(ROOT, "build", "code_compiler", "blitzcc.exe"),
                      os.path.join(ROOT, "build", "distrib", "bin", "blitzcc.exe")):
        if os.path.isfile(candidate):
            return candidate
    return shutil.which("blitzcc") or sys.exit("blitzcc not found, build it or pass --blitzcc.")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--blitzcc")
    parser.add_argument("--textures", type=int, default=int(os.environ.get("BENCH_TEXTURES", 200)))
    parser.add_argument("--objects", type=int, default=int(os.environ.get("BENCH_OBJECTS", 2000)))
    parser.add_argument("--backdrop", type=int, default=int(os.environ.get("BENCH_BACKDROP", 0)), help="size n of a hilly textured terrain of n*n squares behind the cubes")
    parser.add_argument("--sprites", type=int, default=int(os.environ.get("BENCH_SPRITES", 0)), help="how many blended sprites with the small textures lie over the scene")
    parser.add_argument("--frames", type=int, default=int(os.environ.get("BENCH_FRAMES", 300)))
    parser.add_argument("--size", default=os.environ.get("BENCH_SIZE", "640x360"))
    parser.add_argument("--quick", action="store_true", help="40 textures, 400 objects, 30 frames")
    parser.add_argument("--no-atlas", action="store_true", help="BLITZ_NO_TEXTURE_ATLAS=1")
    parser.add_argument("--debug", action="store_true", help="build with -d (no optimization)")
    parser.add_argument("--profile", action="store_true", help="build with --profile, for BLITZ_FPS=1")
    parser.add_argument("--label", default="", help="name of this run in the result, such as the GPU")
    parser.add_argument("--shot", help="save the last frame to this file")
    parser.add_argument("--no-save", action="store_true", help="don't write benchmarks/results/")
    args = parser.parse_args()
    if args.quick:
        args.textures, args.objects, args.frames = 40, 400, 30
    width, height = args.size.lower().split("x")

    compiler = find_compiler(args.blitzcc)
    version = " ".join(procutil.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    llvm = bool(re.search(r"Compiler version:20\d\d\.", version))
    flags = ["-d"] if args.debug else (["-O3"] if llvm else [])
    if args.profile and llvm:
        flags.append("--profile")
    if not llvm and (int(width) > ORIGINAL_MAX_SIZE or int(height) > ORIGINAL_MAX_SIZE):
        sys.exit("The original Blitz3D (Direct3D 7) cannot open a window above %dx%d (asked for %sx%s)." % (ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE, width, height))
    if not llvm:
        os.environ.setdefault("BLITZPATH", os.path.dirname(os.path.dirname(os.path.abspath(compiler))))
        version = " ".join(procutil.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or platform.system() == "Windows" else ["xvfb-run", "-a", "-s", "-screen 0 %sx%sx24" % (width, height)]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")

    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "atlas" + (".exe" if platform.system() == "Windows" else ""))
        source = os.path.join(directory, "atlas.bb")
        shutil.copy(os.path.join(HERE, "atlas.bb"), source)
        shutil.copy(os.path.join(HERE, "atlas_llvm.bi" if llvm else "atlas_original.bi"), os.path.join(directory, "atlas_counters.bi"))
        build = procutil.run([compiler, "-q"] + flags + ["-o", program, source], cwd=directory, capture_output=True, text=True)
        if build.returncode != 0:
            sys.exit("Building the benchmark failed (exit code %d):\n%s" % (build.returncode, (build.stdout + build.stderr)[-2000:]))
        env = dict(os.environ, BENCH_TEXTURES=str(args.textures), BENCH_OBJECTS=str(args.objects), BENCH_BACKDROP=str(args.backdrop), BENCH_SPRITES=str(args.sprites), BENCH_FRAMES=str(args.frames), BENCH_W=width, BENCH_H=height,
                   BENCH_FRAMETIMES=os.path.join(directory, "frametimes.txt"), BENCH_RESULT=os.path.join(directory, "result.txt"))
        if args.no_atlas:
            env["BLITZ_NO_TEXTURE_ATLAS"] = "1"
        if args.profile and llvm:
            env["BLITZ_FPS"] = "1"
        if args.shot:
            env["BENCH_SHOT"] = os.path.abspath(args.shot)
        print("Running %d textures, %d objects, %d backdrop, %d sprites, %d frames, %sx%s, build %s%s" % (args.textures, args.objects, args.backdrop, args.sprites, args.frames, width, height, " ".join(flags), ", atlas off" if args.no_atlas else ""), flush=True)
        # The program writes its pictures to its working directory.
        result = procutil.run(runner + [program], env=env, cwd=directory, capture_output=True, text=True)
        output = result.stdout + result.stderr
        line = None
        if os.path.isfile(env["BENCH_RESULT"]):
            line = next((l for l in open(env["BENCH_RESULT"]).read().splitlines() if "RESULT " in l), None)
        if result.returncode != 0 or line is None:
            sys.exit("The benchmark failed (exit code %d):\n%s" % (result.returncode, output[-2000:]))
        values = {k: float(v) for k, v in re.findall(r"(\w+)=([-+\d.eE]+)", line.split("RESULT ", 1)[1])}
        frametimes = []
        if os.path.isfile(env["BENCH_FRAMETIMES"]):
            frametimes = [int(l) for l in open(env["BENCH_FRAMETIMES"]).read().split()]

    record = {
        "date": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
        "label": args.label,
        "compiler": version if llvm else "Blitz3D " + version,
        "build": " ".join(flags),
        "atlas": not args.no_atlas,
        "platform": platform.platform(),
        "display": "xvfb" if runner else "native",
        "result": values,
    }
    print("\n  textures    %12d, objects %d" % (values["textures"], values["objects"]))
    print("  loading     %12.0f ms for the textures (%.2f ms each)" % (values["load_ms"], values["load_ms"] / max(values["textures"], 1)))
    print("  first frame %12.1f ms (where the textures are merged)" % values["first_ms"])
    print("  ms/frame    avg %.2f  min %.2f  median %.2f  p95 %.2f  max %.2f" % (values["ms_avg"], values["ms_min"], values["ms_median"], values["ms_p95"], values["ms_max"]))
    print("  fps         %12.1f" % values["fps"])
    print("  per frame   %.0f triangles, %.0f draw calls, %.0f texture binds" % (values["tris"], values["draws"], values["textures_bound"]))
    print("  build       %s (%s)%s" % (record["build"] or "no options", version or "unknown compiler", "" if record["atlas"] else ", atlas off"))

    if not args.no_save:
        out = os.path.join(HERE, "results")
        os.makedirs(out, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        name = "atlas-%s-%d-%d-%d" % (stamp, args.textures, args.backdrop, args.sprites)
        with open(os.path.join(out, name + ".json"), "w") as f:
            json.dump(dict(record, frame_times_us=frametimes), f, indent=1)
        csv_path = os.path.join(out, "atlas.csv")
        new = not os.path.isfile(csv_path)
        keys = ("textures", "objects", "backdrop", "sprites", "frames", "load_ms", "first_ms", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps", "tris", "draws", "textures_bound")
        with open(csv_path, "a", newline="") as f:
            writer = csv.writer(f)
            if new:
                writer.writerow(["date", "label", "build", "display", "atlas"] + list(keys))
            writer.writerow([record["date"], args.label, record["build"], record["display"], int(record["atlas"])] + [values[k] for k in keys])
        print("  saved       benchmarks/results/%s.json and atlas.csv" % name)


main()
